  "implementation": "def solve(case):
    initial = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']

    state = initial
    steps_taken = 0
    trace = []
    final_value = None
    status = None

    while steps_taken < max_steps:
        if state not in transitions:
            raise ValueError(f"Unknown state: {state}")
        trans = transitions[state]
        kind = trans.get('kind')
        if kind == 'final':
            final_value = trans.get('value')
            status = 'completed'
            break
        elif kind == 'action':
            action = trans.get('action')
            # Validate tool exists
            if action not in tool_obs:
                raise ValueError(f"Tool '{action}' not found in tool_observations")
            observation = tool_obs[action]
            # Determine next state
            next_by_obs = trans.get('next_by_observation', {})
            default_next = trans.get('default_next')
            if observation in next_by_obs:
                next_state = next_by_obs[observation]
            else:
                if default_next is None:
                    raise ValueError(f"No default_next for state {state}")
                next_state = default_next
            # Record step
            trace.append({
                'step': steps_taken,
                'state': state,
                'action': action,
                'observation': observation
            })
            state = next_state
            steps_taken += 1
        else:
            raise ValueError(f"Invalid transition kind: {kind} in state {state}")
    else:
        # Loop ended due to max_steps without break
        # Check if current state is final (could be final before loop but after break? Not here)
        if state in transitions and transitions[state].get('kind') == 'final':
            final_value = transitions[state].get('value')
            status = 'completed'
        else:
            status = 'max_steps_reached'
            final_value = None

    if status is None:
        # This can happen if initial is final and while loop never entered
        if state in transitions and transitions[state].get('kind') == 'final':
            final_value = transitions[state].get('value')
            status = 'completed'
        else:
            status = 'max_steps_reached'
            final_value = None

    return {
        'final': final_value,
        'status': status,
        'trace': trace
    }
